section.p:
The registering of the user function we use the SaxonProcessor method registerUserFunction:

       void registerUserFunction(const char * ns, XdmValue * (*func)(int, XdmValue **),
           const char * signatureJSON, bool useNativeTypes=false)

p.samp:
XdmValue * myFunc(int length, XdmValue ** values) {
    SaxonProcessor * processor1 = new SaxonProcessor();
    XdmValue * myValue1 = values[0]->getHead();

    if(myValue1->isAtomic()) {
        XdmAtomicValue * item = (XdmAtomicValue *)(myValue1);
        long valuei = item->getLongValue() + 5;

        XdmAtomicValue * resultValue = processor1->makeLongValue(valuei);

        return (XdmValue *)resultValue;
    } else {
        if(values != NULL) {
               return (XdmValue *)values[0];
        }
        return NULL;
    }
}

section.p:
Calling the user extension functions from XSLT, XPath and XQuery is done first by
          declaring the namespace for the function. Then using the function name in your query or stylesheet.
          The arguments passed must match what is declared in the JSON signature.
          For example using the XPath API the following example calls the function:


    xpath->declareNamespace("dy", "http://www.example.com");
    XdmItem *result = xpath->evaluateSingle("dy:myFunc(3)");

pre.code:
char fname[] = "_nativeCall";
char funcParameters[] = "(Ljava/lang/String;[Ljava/lang/Object;[Ljava/lang/String;)Ljava/lang/Object;";

JNINativeMethod cppMethods[] =
{
  {
    fname,
    funcParameters,
    (void *)&cppNativeCall
  }
};

/*
* Test transform to String. Source and stylesheet supplied as arguments
*/
void testTransformToStringExtensionFunc(SaxonProcessor * processor, XsltProcessor * trans){

  trans->setProperty("extc", "/path/cppExtensionFunction");

  bool nativeFound = processor->registerNativeMethods(SaxonProcessor::sxn_environ->env,
      "com/saxonica/functions/extfn/cpp/NativeCall",
      cppMethods, sizeof(cppMethods) / sizeof(cppMethods[0]));

  if(nativeFound) {
    const char * output = trans->transformFileToString("cat.xml", "testExtension.xsl");

    if(output == NULL) {
      printf("result is null \n");

    } else {
      //printf("%s", output);
      printf("result is OK \n");
    }
    fflush(stdout);
    delete output;

  } else {
    printf("native Class not found");
  }
}

// define an extension function
function userFunction($param , $param2)
{
  if(is_numeric($param2)){
    echo("userspace function called cp1\n");
    $result = $param2*2;
    return $result;
  }
}

function userFunctionExample($saxon, $proc, $xmlfile, $xslFile){
  echo '<b>userFunctionExample:</b><br/>';
  global $resultg;

  $saxon->registerPHPFunctions(" /usr/lib/php/20190718/saxon");
  $proc->setSourceFromFile($xmlfile);
  $proc->compileFromFile($xslFile);

  $result = $proc->transformToString();
  if($result != null) {
    echo 'Output=======:'.$result;
  } else {
    echo "Result is null";
    if($proc->exceptionOccurred()){
      echo 'Error Message='.$proc->getErrorMessage();
    }
  }

  $proc->clearParameters();
  $proc->clearProperties();

}
